# solution.py

class InsufficientFunds(Exception):
    """Exception raised when a withdrawal exceeds the account balance."""
    pass


class BankAccount:
    """A simple bank account with deposit, withdraw, and transaction history."""

    def __init__(self, owner: str, balance: float = 0):
        if balance < 0:
            raise ValueError("Starting balance cannot be negative")
        self._owner = owner
        self._balance = float(balance)
        self._history = []  # type: list[tuple[str, float]]

    @property
    def owner(self) -> str:
        """The name of the account holder."""
        return self._owner

    @property
    def balance(self) -> float:
        """Current balance (read‑only)."""
        return self._balance

    @property
    def history(self) -> list[tuple[str, float]]:
        """List of successful transactions as (type, amount) tuples."""
        # Return a copy to prevent external mutation
        return list(self._history)

    def deposit(self, amount: float) -> None:
        """Add funds to the account.

        Args:
            amount: Positive amount to deposit.

        Raises:
            ValueError: If amount is not positive.
        """
        if amount <= 0:
            raise ValueError("Deposit amount must be greater than zero")
        self._balance += float(amount)
        self._history.append(("deposit", float(amount)))

    def withdraw(self, amount: float) -> None:
        """Remove funds from the account.

        Args:
            amount: Positive amount to withdraw.

        Raises:
            ValueError: If amount is not positive.
            InsufficientFunds: If amount exceeds the current balance.
        """
        if amount <= 0:
            raise ValueError("Withdrawal amount must be greater than zero")
        if amount > self._balance:
            raise InsufficientFunds("Insufficient funds for withdrawal")
        self._balance -= float(amount)
        self._history.append(("withdraw", float(amount)))
